import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.DcUzesGg.js";var i=JSON.parse(`{"title":"Explicit reconstruction","description":"","frontmatter":{},"headers":[],"relativePath":"guide/explicit.md","filePath":"guide/explicit.md","lastUpdated":0}`),a={name:`guide/explicit.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="explicit-reconstruction" tabindex="-1">Explicit reconstruction <a class="header-anchor" href="#explicit-reconstruction" aria-label="Permalink to “Explicit reconstruction”">​</a></h1><p><code>HighOrderExplicitOp</code> is the Explicit family entry. It returns an existing concrete operator; it adds neither a new numerical model nor a workspace layer.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Implementation</th><th style="text-align:left;">Selection</th><th style="text-align:left;">Solver storage</th><th style="text-align:left;">Detail</th></tr></thead><tbody><tr><td style="text-align:left;">Array</td><td style="text-align:left;"><code>implementation=:array</code></td><td style="text-align:left;">Selected by <code>arrayType</code></td><td style="text-align:left;"><a href="/HighOrderMRI.jl/stable/guide/explicit-array">Array</a></td></tr><tr><td style="text-align:left;">Direct kernel (host vectors)</td><td style="text-align:left;"><code>implementation=:kernel, backend=:legacy</code></td><td style="text-align:left;">Host</td><td style="text-align:left;"><a href="/HighOrderMRI.jl/stable/guide/explicit-kernel">Direct kernel</a></td></tr><tr><td style="text-align:left;">Direct kernel (GPU resident)</td><td style="text-align:left;"><code>implementation=:kernel, backend=:direct</code></td><td style="text-align:left;">Primary GPU</td><td style="text-align:left;"><a href="/HighOrderMRI.jl/stable/guide/explicit-kernel#resident-direct-evaluation">Direct kernel</a></td></tr><tr><td style="text-align:left;">GEMM and phase-reuse (blocked)</td><td style="text-align:left;"><code>implementation=:kernel, backend=:blocked</code></td><td style="text-align:left;">Primary GPU</td><td style="text-align:left;"><a href="/HighOrderMRI.jl/stable/guide/explicit-gemm">Phase reuse</a></td></tr><tr><td style="text-align:left;">GEMM and phase-reuse (cached)</td><td style="text-align:left;"><code>implementation=:kernel, backend=:cached</code> or <code>:cached_full</code></td><td style="text-align:left;">Primary GPU</td><td style="text-align:left;"><a href="/HighOrderMRI.jl/stable/guide/explicit-gemm">Caching</a></td></tr></tbody></table><p>The method tree distinguishes Array from CUDA acceleration. The CUDA acceleration branch uses the existing selector <code>implementation=:kernel</code>; this name and its behavior are unchanged. Its computation paths are Direct kernel and GEMM and phase-reuse. <code>backend</code> chooses their execution modes. <code>phase_backend</code> chooses how matrix phase blocks are generated; <code>gemm_backend</code> chooses their matrix multiplication implementation. These choices do not introduce low-rank truncation.</p><p>The default family selection is Array with the original <code>arrayType=CuArray</code>. For a CPU reference explicitly pass <code>arrayType=Array</code>. The CUDA implementation uses <code>backend=:legacy</code> by default. All Explicit operators are constructed through <code>HighOrderExplicitOp</code>.</p><h2 id="readout-layout" tabindex="-1">Readout layout <a class="header-anchor" href="#readout-layout" aria-label="Permalink to “Readout layout”">​</a></h2><p>Explicit implementations accept <code>(nTerm,N)</code> coefficients and <code>N</code> times. For several readouts of one image, flatten the sample/readout axes with samples varying fastest. Flatten data in the same order, retaining coils as the final axis. This combines all measurements without deleting samples or changing the physical model. LowRank also accepts a separate readout axis directly.</p><h2 id="common-contracts" tabindex="-1">Common contracts <a class="header-anchor" href="#common-contracts" aria-label="Permalink to “Common contracts”">​</a></h2><p>All paths use the <a href="/HighOrderMRI.jl/stable/theory/encoding-model">same physical model</a>, mask and symmetric voxel normalization. Pass raw square-root sample weights to <code>recon_HOOp</code>; <code>normalOperator(op,D)</code> instead receives the already squared diagonal. Derivative <code>kspha_dt</code> modes have a forward-only limitation described in the Array and Direct kernel pages and must not be used for ordinary CG normals.</p><p>Use the <a href="/HighOrderMRI.jl/stable/reference/highorderexplicitop">Explicit API</a> for the family wrapper, the <a href="/HighOrderMRI.jl/stable/guide/reconstruction">reconstruction workflow</a> for solving, and the <a href="/HighOrderMRI.jl/stable/reference/resources">resource reference</a> for CUDA lifecycle management.</p>`,10)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};